const TELEGRAM_TOKEN = env.get("TELEGRAM_TOKEN");

msg.chatId = msg.payload.chatId;

if (!TELEGRAM_TOKEN) {
    msg.payload = {
        chatId: msg.chatId,
        type: "message",
        content: "Token do Telegram não configurado. Defina a variável TELEGRAM_TOKEN no ambiente do Node-RED."
    };

    return [null, msg];
}

let fileId = msg.payload.content;

if (!fileId) {
    msg.payload = {
        chatId: msg.chatId,
        type: "message",
        content: "Não consegui identificar o áudio enviado."
    };

    return [null, msg];
}

try {
    let urlGetFile =
        "https://api.telegram.org/bot" +
        TELEGRAM_TOKEN +
        "/getFile?file_id=" +
        fileId;

    let respostaGetFile = await fetch(urlGetFile);
    let dadosArquivo = await respostaGetFile.json();

    if (!dadosArquivo.ok || !dadosArquivo.result || !dadosArquivo.result.file_path) {
        node.warn(dadosArquivo);

        msg.payload = {
            chatId: msg.chatId,
            type: "message",
            content: "Não consegui baixar o áudio enviado. Tente mandar outro áudio."
        };

        return [null, msg];
    }

    let filePath = dadosArquivo.result.file_path;

    let urlDownload =
        "https://api.telegram.org/file/bot" +
        TELEGRAM_TOKEN +
        "/" +
        filePath;

    let respostaAudio = await fetch(urlDownload);

    if (!respostaAudio.ok) {
        throw new Error("Erro ao baixar áudio: " + respostaAudio.status);
    }

    let arrayBuffer = await respostaAudio.arrayBuffer();

    msg.payload = Buffer.from(arrayBuffer);

    return [msg, null];

} catch (erro) {
    node.error(erro);

    msg.payload = {
        chatId: msg.chatId,
        type: "message",
        content: "Erro ao baixar o áudio do Telegram. Verifique o token do bot."
    };

    return [null, msg];
}

let texto = "";

try {
    if (
        msg.payload &&
        msg.payload.results &&
        msg.payload.results.length > 0 &&
        msg.payload.results[0].alternatives &&
        msg.payload.results[0].alternatives.length > 0
    ) {
        texto = msg.payload.results[0].alternatives[0].transcript;
    }
} catch (erro) {
    node.warn(erro);
}

texto = String(texto || "").trim();

if (!texto) {
    msg.payload = {
        chatId: msg.chatId,
        type: "message",
        content: "Não consegui entender o áudio. Tente falar mais perto do microfone."
    };

    return [null, msg];
}

let msgParaWatson = {
    payload: {
        chatId: msg.chatId,
        type: "message",
        content: texto
    }
};

let msgConfirmacao = {
    payload: {
        chatId: msg.chatId,
        type: "message",
        content: "Entendi seu áudio como: \"" + texto + "\""
    }
};

return [msgParaWatson, msgConfirmacao];

msg.chatId = msg.payload.chatId;

let textoUsuario =
    msg.payload.content ||
    msg.payload.text ||
    msg.payload.command ||
    msg.payload.message ||
    "";

textoUsuario = String(textoUsuario).trim();
let textoMinusculo = textoUsuario.toLowerCase();

let boasVindas =
    "Olá! Seja bem-vindo ao atendimento virtual da AstroNet. 🚀\n\n" +
    "Eu sou o assistente inteligente da AstroNet e posso ajudar você com dúvidas sobre internet via satélite, cobertura em regiões remotas, planos, instalação, equipamentos, suporte técnico e contratação.\n\n" +
    "Você pode perguntar, por exemplo:\n" +
    "• Como funciona a internet via satélite?\n" +
    "• A AstroNet atende áreas rurais?\n" +
    "• Quais planos a AstroNet oferece?\n" +
    "• Como funciona a instalação?\n" +
    "• Solicitar orçamento\n\n" +
    "Como posso ajudar você hoje?";

if (
    textoMinusculo === "/start" ||
    textoMinusculo === "start" ||
    textoMinusculo === "/restart" ||
    textoMinusculo === "restart" ||
    textoMinusculo === "/help" ||
    textoMinusculo === "oi" ||
    textoMinusculo === "olá" ||
    textoMinusculo === "ola"
) {
    flow.set("watson_context_" + msg.chatId, null);

    let msgTexto = {
        payload: {
            chatId: msg.chatId,
            type: "message",
            content: boasVindas
        }
    };

    let msgTTS = {
        chatId: msg.chatId,
        respostaTexto: boasVindas
    };

    return [null, msgTexto, msgTTS];
}

if (!textoUsuario) {
    msg.payload = {
        chatId: msg.chatId,
        type: "message",
        content: "Não entendi sua mensagem. Envie texto ou áudio."
    };

    return [null, msg, null];
}

let contextoSalvo = flow.get("watson_context_" + msg.chatId) || {};

msg.payload = textoUsuario;

msg.params = {
    input: {
        message_type: "text",
        text: textoUsuario
    },
    context: contextoSalvo
};

return [msg, null, null];

let resposta = "Desculpe, não consegui entender sua pergunta.";

try {
    if (msg.payload && msg.chatId) {
        if (msg.payload.context) {
            flow.set("watson_context_" + msg.chatId, msg.payload.context);
        }

        if (
            msg.payload.output &&
            msg.payload.output.generic &&
            msg.payload.output.generic.length > 0
        ) {
            let textos = msg.payload.output.generic
                .filter(item => item.response_type === "text")
                .map(item => item.text);

            if (textos.length > 0) {
                resposta = textos.join("\n\n");
            }
        }
    }
} catch (erro) {
    node.warn(erro);
    resposta = "Ocorreu um erro ao processar a resposta da AstroNet.";
}

let msgTexto = {
    payload: {
        chatId: msg.chatId,
        type: "message",
        content: resposta
    }
};

let msgTTS = {
    chatId: msg.chatId,
    respostaTexto: resposta
};

return [msgTexto, msgTTS];

let texto = msg.respostaTexto || "Olá, sou o assistente da AstroNet.";

texto = texto
    .replace(/\n+/g, " ")
    .replace(/•/g, "")
    .replace(/-/g, "")
    .replace(/\*/g, "")
    .replace(/_/g, "")
    .trim();

if (texto.length > 3500) {
    texto = texto.substring(0, 3500) + "... Para mais detalhes, veja a resposta em texto.";
}

msg.payload = texto;

return msg;

msg.payload = {
    chatId: msg.chatId,
    type: "document",
    content: msg.payload,
    caption: "Resposta em áudio da AstroNet",
    filename: "resposta-astronet.mp3"
};

return msg;
